  init: GS { strict: false, cache: None, age: 0, probe_fails: false, bad: false, refused: false, writes: 0 }
   1. SetStrict(true)
      -> GS { strict: true, cache: None, age: 0, probe_fails: false, bad: false, refused: false, writes: 0 }
   2. UnguardedWrite
      -> GS { strict: true, cache: None, age: 0, probe_fails: false, bad: true, refused: false, writes: 1 }
